DROP TABLE IF EXISTS `mou_signature_boxes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mou_signature_boxes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `mou_id` int NOT NULL,
  `user_id` int NOT NULL,
  `role_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `page_number` int NOT NULL,
  `pos_x` float NOT NULL,
  `pos_y` float NOT NULL,
  `width` float NOT NULL,
  `height` float NOT NULL,
  `is_signed` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `mou_id` (`mou_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `mou_signature_boxes_ibfk_1` FOREIGN KEY (`mou_id`) REFERENCES `mou_documents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mou_signature_boxes_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=634 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
