--
-- Table structure for table `mou_signatures`
--

DROP TABLE IF EXISTS `mou_signatures`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mou_signatures` (
  `id` int NOT NULL AUTO_INCREMENT,
  `mou_id` int NOT NULL,
  `box_id` int NOT NULL,
  `user_id` int NOT NULL,
  `user_signature_id` int DEFAULT NULL,
  `signature_image_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `signed_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `box_id` (`box_id`),
  KEY `mou_id` (`mou_id`),
  KEY `user_id` (`user_id`),
  KEY `user_signature_id` (`user_signature_id`),
  CONSTRAINT `mou_signatures_ibfk_1` FOREIGN KEY (`mou_id`) REFERENCES `mou_documents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mou_signatures_ibfk_2` FOREIGN KEY (`box_id`) REFERENCES `mou_signature_boxes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mou_signatures_ibfk_3` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `mou_signatures_ibfk_4` FOREIGN KEY (`user_signature_id`) REFERENCES `user_signatures` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=221 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

